window.SPEC_CWT_ENGINE={
 cwtCode(value){return String(value||'').match(/BWH-(?:620[DE]|720[FG])/i)?.[0].toUpperCase()||'';},
 lookup({capacity,speed,jj,entrance,fire,cwt}){
   const code=String(capacity??'').split(' (')[0];const sp=Number(speed)>=120?'H':'L';
   const door=String(entrance);const fireValue=String(fire??'');const fc=(fireValue===''||/Not suppl/i.test(fireValue)||fireValue==='GHCL E30')?'NO':'YES';
   const item=window.SPEC_CWT_DATA.find(r=>r.model===code&&r.speed===sp&&r.jj===Number(jj)&&r.entrance===door&&r.fire===fc);
   if(!item)return {ok:false,reason:'layout',code};
   const selected=this.cwtCode(cwt);
   if(selected===item.baseCwt)return {ok:true,AH:item.baseAH,BH:item.baseBH,cwt:selected,item};
   if(selected===item.altCwt)return {ok:true,AH:item.altAH,BH:item.altBH,cwt:selected,item};
   return {ok:false,reason:'cwt',selected,item};
 },
 lookupEngine(calc){
  const v=cell=>{const res=calc.safe('SpecForm',cell);return res.ok?res.value:null};
  return this.lookup({capacity:v('D13'),speed:v('D17'),jj:v('D31'),entrance:v('D16'),fire:v('D84'),cwt:v('D23')});
 },
 check(calc,issue,unverified,verified){
   const record=this.lookupEngine(calc);
   if(!record.ok){
     if(record.reason==='cwt')issue('CWT!TYPE','D23','Đối trọng '+(record.selected||'(trống)')+' chưa có AH/BH theo tổ hợp đang chọn; không sử dụng kích thước của 620D/720F thay thế.');
     else issue('CWT!LOOKUP','D31','Không có dữ liệu AH/BH cho tổ hợp Model / Speed / JJ / Entrance / Fire hiện tại.');
     return;
   }
   for(const [kind,cell,limit] of [['AH','D33',record.AH],['BH','D34',record.BH]]){
     const v=calc.safe('SpecForm',cell);const val=v.ok?Number(v.value):NaN;
     if(!Number.isFinite(val)||val<limit){
       issue('CWT!'+kind,cell,kind+' '+(Number.isFinite(val)?val+' mm':'chưa nhập')+' < tối thiểu '+limit+' mm đối với '+record.cwt+'.');
     }
   }
   verified.push('CWT-specific AH/BH: 156 rows, 620D/E and 720F/G');
 },
 applyDataset(db,model){
   if(!db?.sheets?.DataTable||!db?.sheets?.SpecForm)return;
   if(model==='MRL'){
    const sh=db.sheets.DataTable;
    if(!window.SPEC_CWT_DATA.every(r=>String(sh['AL'+r.row])===r.model&&Number(sh['AN'+r.row])===r.jj)){
      db.__cwtDatasetMismatch=true;return;
    }
    for(const r of window.SPEC_CWT_DATA){sh['AQ'+r.row]=r.baseAH;sh['AR'+r.row]=r.baseBH;sh['DQ'+r.row]=r.altCwt;sh['DR'+r.row]=r.altAH;sh['DS'+r.row]=r.altBH;}
    sh.DQ1='Alternate CWT code (V02)';sh.DR1='Alternate AH min (mm)';sh.DS1='Alternate BH min (mm)';
   }
   for(const [key,formula] of Object.entries(window.SPEC_SOURCE_PATCHES[model]||{})){
    const [sheet,cell]=key.split('!');const prev=db.sheets[sheet][cell];
    db.sheets[sheet][cell]={f:formula.replace(/^=/,''),v:prev&&typeof prev==='object'?prev.v:prev};
   }
 }
};
for(const model of ['MR','MRL'])window.SPEC_CWT_ENGINE.applyDataset(window.SPEC_ENGINE_DATABASE?.[model],model);
